create extension if not exists pgcrypto;
create table public.extensions(id text primary key,name text not null,display_name text not null,publisher text not null,description text not null default '',registry text not null check(registry in ('vs-marketplace','openvsx')),publisher_verified boolean not null default false,installs bigint not null default 0,rating numeric not null default 0,icon_url text not null default '',repository_url text not null default '',first_published_at timestamptz,last_published_at timestamptz,catalog_rank integer,updated_at timestamptz not null default now());
create table public.extension_versions(extension_id text not null references public.extensions(id) on delete cascade,version text not null,registry text not null,published_at timestamptz,artifact_sha256 text,artifact_size bigint,download_url text,is_latest boolean not null default false,is_removed boolean not null default false,scan_state text not null default 'not_scanned' check(scan_state in ('not_scanned','queued','running','complete','incomplete','failed')),latest_scan_id uuid,metadata jsonb not null default '{}'::jsonb,primary key(extension_id,version));
create table public.scan_jobs(id uuid primary key default gen_random_uuid(),extension_id text not null references public.extensions(id) on delete cascade,version text not null,profile text not null check(profile in ('quick','deep')),status text not null default 'queued' check(status in ('queued','running','complete','incomplete','failed')),requested_by uuid references auth.users(id) on delete set null,requester_hash text,github_run_id bigint,ruleset_version text,error text,created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz);
create unique index scan_jobs_active_artifact on public.scan_jobs(extension_id,version,profile) where status in ('queued','running');
create table public.scans(id uuid primary key default gen_random_uuid(),job_id uuid unique references public.scan_jobs(id) on delete set null,extension_id text not null,version text not null,artifact_sha256 text not null,profile text not null,schema_version text not null,scanner_version text not null,ruleset_version text not null,decision text not null check(decision in ('allow','review','block','incomplete')),decision_reason text not null,verdict text not null,severity text not null,risk_score integer not null default 0,malware_score integer not null default 0,coverage_percent integer not null default 0,provider_coverage jsonb not null default '{}'::jsonb,security_dimensions jsonb not null default '{}'::jsonb,manifest jsonb not null default '{}'::jsonb,artifact_inventory jsonb not null default '{}'::jsonb,capabilities jsonb not null default '{}'::jsonb,baseline_diff jsonb not null default '{}'::jsonb,canonical_report jsonb not null,scanned_at timestamptz not null default now(),unique(extension_id,version,artifact_sha256,ruleset_version));
alter table public.extension_versions add constraint extension_versions_latest_scan_fk foreign key(latest_scan_id) references public.scans(id) on delete set null;
create table public.findings(id text not null,scan_id uuid not null references public.scans(id) on delete cascade,rule_id text not null,category text not null,severity text not null,confidence numeric not null default 0,evidence_class text not null,actionability text not null,summary text not null,recommendation text not null default '',file_refs jsonb not null default '[]'::jsonb,evidence jsonb not null default '{}'::jsonb,primary key(scan_id,id));
create table public.artifact_files(scan_id uuid not null references public.scans(id) on delete cascade,path text not null,sha256 text not null,size_bytes bigint not null default 0,kind text not null default 'file',target text,primary key(scan_id,path));
create table public.dependencies(scan_id uuid not null references public.scans(id) on delete cascade,name text not null,version text not null,ecosystem text not null default 'npm',relationship text not null check(relationship in ('direct','transitive')),advisories jsonb not null default '[]'::jsonb,primary key(scan_id,ecosystem,name,version));;
